<?php
$rooms = PG::roomsForOwner((int) current_user()['id']);
$pgs = PG::byOwner((int) current_user()['id']);
$flash = get_flash();
?><!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Room Management</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{font-family:Inter,Arial,sans-serif;background:#f5f7ff;color:#111827}.page{max-width:1200px;margin:0 auto;padding:28px 18px 60px}.room-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.room-card,.form-panel{background:#fff;border:1px solid rgba(15,23,42,.08);border-radius:22px;padding:20px;box-shadow:0 20px 30px rgba(15,23,42,.04)}.bed-row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eef0f4}.status{border-radius:999px;padding:6px 10px;font-size:.75rem;font-weight:700;background:#ecfdf5;color:#15803d}@media(max-width:900px){.room-grid{grid-template-columns:1fr}}</style></head>
<body><div class="page"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="text-primary fw-bold">Room Inventory</div><h1 class="mb-0">Manage Rooms</h1></div><a class="btn btn-dark" href="#roomForm">+ Add Room</a></div><?php if ($flash): ?><div class="alert alert-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><form id="roomForm" class="form-panel mb-4" method="post" action="/owner/room/create"><h5>Add room</h5><?= csrf_field() ?><div class="row g-3"><div class="col-md-3"><label class="form-label">Property</label><select class="form-select" name="pg_id" required><?php foreach ($pgs as $pg): ?><option value="<?= (int) $pg['id'] ?>"><?= e($pg['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Room number</label><input class="form-control" name="room_number" required></div><div class="col-md-2"><label class="form-label">Type</label><select class="form-select" name="room_type"><option value="single">Single</option><option value="double">Double</option><option value="triple">Triple</option></select></div><div class="col-md-2"><label class="form-label">Rent</label><input class="form-control" type="number" name="rent" min="0" required></div><div class="col-md-2"><label class="form-label">Beds</label><input class="form-control" type="number" name="beds_total" min="1" max="26" required></div></div><button class="btn btn-primary mt-3" type="submit">Create room</button></form><div class="room-grid"><?php foreach ($rooms as $room): $beds = PG::bedsForRoom((int) $room['id']); $occupied = count(array_filter($beds, fn($bed) => $bed['status'] === 'occupied')); ?><article class="room-card"><div class="d-flex justify-content-between align-items-center"><h4 class="mb-0">Room <?= e($room['room_number']) ?></h4><span class="status"><?= $occupied === count($beds) ? 'Full' : 'Available' ?></span></div><div class="mt-2 text-secondary"><?= e(ucfirst($room['room_type'])) ?> sharing • <?= e($room['pg_name']) ?></div><div class="mt-3 fw-bold fs-5">₹<?= number_format((float) $room['rent'], 0) ?> / month</div><div class="mt-3"><?php foreach ($beds as $bed): ?><div class="bed-row"><span><?= e('Bed ' . $bed['bed_number']) ?></span><span class="text-<?= $bed['status'] === 'occupied' ? 'danger' : 'success' ?>"><?= e(ucfirst($bed['status'])) ?></span></div><?php endforeach; ?></div><div class="mt-3 small text-secondary"><?= $occupied ?> / <?= count($beds) ?> occupied</div></article><?php endforeach; ?></div></div></body></html>
